/* connContextMenuSafe 2026-11-24 - connection card right-click menu */
(function () {
  if (window.__dbStudioConnMenuInstalled) return;
  window.__dbStudioConnMenuInstalled = true;

  var menu = document.createElement("div");
  menu.className = "conn-ctx-menu";
  menu.innerHTML =
    '<div class="conn-ctx-item" data-act="test">测试连接</div>' +
    '<div class="conn-ctx-item" data-act="edit">编辑连接…</div>' +
    '<div class="conn-ctx-sep"></div>' +
    '<div class="conn-ctx-item danger" data-act="delete">删除连接…</div>';
  document.body.appendChild(menu);

  var currentCard = null;
  function hide() {
    menu.style.display = "none";
    currentCard = null;
  }
  function show(x, y, card) {
    currentCard = card;
    menu.style.display = "block";
    var w = menu.offsetWidth, h = menu.offsetHeight;
    var left = x, top = y;
    if (left + w > window.innerWidth - 4) left = window.innerWidth - w - 4;
    if (top + h > window.innerHeight - 4) top = window.innerHeight - h - 4;
    menu.style.left = Math.max(2, left) + "px";
    menu.style.top = Math.max(2, top) + "px";
  }

  document.addEventListener("contextmenu", function (ev) {
    var t = ev.target;
    var card = t && t.closest ? t.closest(".connection-card") : null;
    if (!card) { hide(); return; }
    ev.preventDefault();
    ev.stopPropagation();
    show(ev.clientX, ev.clientY, card);
  }, true);

  menu.addEventListener("mousedown", function (ev) {
    var item = ev.target && ev.target.closest ? ev.target.closest(".conn-ctx-item") : null;
    if (!item) return;
    var act = item.getAttribute("data-act");
    var card = currentCard;
    hide();
    if (!card) return;
    var btns = card.querySelectorAll(".connection-tools button");
    var idx = act === "test" ? 0 : act === "edit" ? 1 : 2;
    var btn = btns[idx];
    if (btn) btn.click();
  });

  document.addEventListener("mousedown", function (ev) {
    if (!menu.contains(ev.target)) hide();
  }, true);
  document.addEventListener("keydown", function (ev) {
    if (ev.key === "Escape") hide();
  });
  window.addEventListener("resize", hide);
  window.addEventListener("scroll", hide, true);
})();
